package com.sgasubtitler.engine;
import com.sgasubtitler.model.*; import java.awt.*; import java.awt.image.*; import java.io.*; import java.util.*;
public final class C1Codec {
 public BufferedImage decode(SgaChunk c,int[][] inherited)throws IOException{byte[] d=c.data();int flags=d[4]&255,pc=d[5]&255,w=d[6]&255,h=d[7]&255,meta=(flags&128)!=0?10:8;byte[] body=d;if(Set.of(0xC6,0xC7,0xC8,0xC9,0xCB,0xCD).contains(c.type())){int mask=(c.type()==0xCB||c.type()==0xCD)?0xF000:0xE000,base=Set.of(0xC7,0xC9,0xCB,0xCD).contains(c.type())?1:0;byte[] unpack=LzDecoder.decode(Arrays.copyOfRange(d,meta,d.length),mask,base);body=new byte[meta+unpack.length];System.arraycopy(d,0,body,0,meta);System.arraycopy(unpack,0,body,meta,unpack.length);}int tileCount=(flags&128)!=0?u16(body,8):w*h,tileLen=tileCount*32,palLen=pc*18;int tileOff=(flags&4)!=0?meta:meta+palLen,palOff=(flags&4)!=0?meta+tileLen:meta;byte[] tiles=Arrays.copyOfRange(body,tileOff,Math.min(body.length,tileOff+tileLen));if(Set.of(0xC8,0xC9,0xCD).contains(c.type())&&(flags&128)==0)for(int i=4;i<tiles.length;i+=8)for(int j=0;j<4&&i+j<tiles.length;j++)tiles[i+j]=(byte)(((tiles[i+j]&255)>>>4)|((tiles[i+j]&15)<<4));int[][] palettes=pc>0?palettes(body,palOff,pc):inherited;if(palettes==null)palettes=new int[][]{gray()};byte[] pmap=Arrays.copyOfRange(body,Math.min(body.length,palOff+palLen),body.length);BufferedImage image=new BufferedImage(w*8,h*8,BufferedImage.TYPE_INT_RGB);int bits=pc==2?1:2;for(int ty=0;ty<h;ty++)for(int tx=0;tx<w;tx++){int ti=ty*w+tx,pi=0;if(pc>1&&(flags&128)==0){int pp=ti/(8/bits);if(pp<pmap.length)pi=((pmap[pp]&255)>>(8-bits-bits*(ti%(8/bits))))&((1<<bits)-1);pi=Math.min(pi,palettes.length-1);}for(int y=0;y<8;y++)for(int x=0;x<8;x++){int at=ti*32+y*4+x/2;if(at<tiles.length){int v=tiles[at]&255,ci=(x&1)==0?v>>>4:v&15;image.setRGB(tx*8+x,ty*8+y,palettes[pi][ci]);}}}return image;}
 public int[][] palettes(SgaChunk c){byte[]d=c.data();int flags=d[4]&255,pc=d[5]&255,w=d[6]&255,h=d[7]&255,meta=(flags&128)!=0?10:8,tileLen=((flags&128)!=0?u16(d,8):w*h)*32,palOff=(flags&4)!=0?meta+tileLen:meta;return pc==0?null:palettes(d,palOff,pc);}
 private static int[][] palettes(byte[]d,int off,int count){int[][]p=new int[count][16];for(int n=0;n<count;n++)for(int color=0;color<16;color++){int rgb=0;for(int ch=0;ch<3;ch++){int val=0;for(int pow=0;pow<3;pow++){int q=off+n*18+ch*6+pow*2;if(q+1<d.length){int bit=color<8?((d[q]&255)>>color)&1:((d[q+1]&255)>>(color-8))&1;val|=bit<<pow;}}rgb|=(val*36)<<(16-ch*8);}p[n][color]=rgb;}return p;}
 private static int[]gray(){int[]x=new int[16];for(int i=0;i<16;i++)x[i]=(i*17<<16)|(i*17<<8)|i*17;return x;}private static int u16(byte[]b,int p){return((b[p]&255)<<8)|(b[p+1]&255);}
}
